CREATE TABLE credit_config (id INT PRIMARY KEY, config_json LONGTEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE credit_wallets (user_id VARCHAR(191) COLLATE utf8mb4_bin PRIMARY KEY, balance BIGINT NOT NULL DEFAULT 0 CHECK(balance BETWEEN 0 AND 1000000000), frozen BIGINT NOT NULL DEFAULT 0 CHECK(frozen >= 0 AND frozen <= balance)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE credit_gift_claims (user_id VARCHAR(191) COLLATE utf8mb4_bin PRIMARY KEY, created_at VARCHAR(32) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE credit_codes (id VARCHAR(36) PRIMARY KEY, code_hash CHAR(64) COLLATE utf8mb4_bin NOT NULL UNIQUE, credits BIGINT NOT NULL, label VARCHAR(200) NOT NULL, expires_at VARCHAR(32), disabled INT NOT NULL DEFAULT 0, redeemed_by VARCHAR(191) COLLATE utf8mb4_bin, redeemed_at VARCHAR(32), created_by VARCHAR(191), created_at VARCHAR(32) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE credit_reservations (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(191) COLLATE utf8mb4_bin NOT NULL, request_id VARCHAR(191) COLLATE utf8mb4_bin NOT NULL UNIQUE, model_record_id VARCHAR(191) COLLATE utf8mb4_bin, count INT NOT NULL, unit_credits BIGINT NOT NULL, reserved_credits BIGINT NOT NULL, success_count INT, created_at VARCHAR(32) NOT NULL, settled_at VARCHAR(32)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE credit_ledger (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(191) COLLATE utf8mb4_bin NOT NULL, kind VARCHAR(32) NOT NULL, amount BIGINT NOT NULL, reference_id VARCHAR(36), created_at VARCHAR(32) NOT NULL, INDEX credit_ledger_user(user_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
